contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: attempt a Deposit of amount 'depositAmt' and assert the exact accounting effect when it doesn't revert
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // require we have funds to send
        require(address(this).balance >= depositAmt);

        // read before-values
        uint beforeContractBal = address(c).balance;
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // attempt Deposit and capture whether it reverted
        bool depositReverted;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        // read after-values
        uint afterContractBal = address(c).balance;
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // Assert the general rule: if Deposit succeeded then contract balance and recorded balance increased by exactly depositAmt
        assert(depositReverted || (afterContractBal == beforeContractBal + depositAmt && afterRecorded == beforeRecorded + depositAmt));
    }

    // allow this test contract to receive ETH refunds
    receive() external payable {}
}

