// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        uint beforeContractBal = address(c).balance;
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        bool depositReverted;
        try c.Deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        uint afterContractBal = address(c).balance;
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        assertTrue(depositReverted || (afterContractBal == beforeContractBal + depositAmt && afterRecorded == beforeRecorded + depositAmt));
    }

    function testFuzz_run(uint256 depositAmt) public {
        _run(depositAmt);
    }

    receive() external payable {}
}
